-- models/marts/dim_contact.sql  (dbt incremental)
{{ config(materialized='incremental', unique_key='contact_sk') }}

with deduped as (
    select
        {{ dbt_utils.generate_surrogate_key(['email','company_domain']) }} as contact_sk,
        *,
        row_number() over (
            partition by lower(email)
            order by source_priority, updated_at desc
        ) as rn
    from {{ ref('stg_contacts') }}
    {% if is_incremental() %}
      where updated_at > (select max(updated_at) from {{ this }})
    {% endif %}
)
select * exclude (rn)
from deduped
where rn = 1
